beforeExample:
package test;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class MyTest {
    public boolean someMethod() { return true; }

    @Test
    public void testSomething() {
        boolean condition = true;
        assertEquals(true, condition);
        assertEquals(true, someMethod());
    }
}

afterExample:
package test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class MyTest {
    public boolean someMethod() { return true; }

    @Test
    public void testSomething() {
        boolean condition = true;
        assertTrue(condition);
        assertTrue(someMethod());
    }
}

negativeExample:
package test;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class MyTest {
    public boolean someMethod() { return true; }

    @Test
    public void testSomethingElse() {
        assertEquals("message", true, true); // Has 3 args
        assertEquals("message", someMethod(), true); // true is not the first arg (2nd argument)
        assertEquals(1, 1); // Not assertEquals(true, ...)
        assertEquals(false, someMethod()); // different literal
    }
}
